create table if not exists privacy_notices(id text primary key,tenant_id text not null,version text not null,content_hash text not null,effective_at timestamptz not null,unique(tenant_id,version));create table if not exists consent_records(id text primary key,tenant_id text not null,candidate_id text not null,notice_version text not null,accepted_at timestamptz not null);create table if not exists privacy_requests(id text primary key,tenant_id text not null,candidate_id text not null,type text not null,status text not null default 'OPEN',created_at timestamptz not null default now(),completed_at timestamptz);